    {
      "benefit": "CI",
      "years": [2019, 2023],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.14 cumulative (A/E 0.97 to 1.11), peaking at +0.11 in 2022/2023",
      "confidence": 0.85,
      "evidence": [
        "ae_ci_by_year.csv: sustained YoY rise from 2019 (0.971) through 2023 (1.110)",
        "3y MA fit R2=0.83 with gradient ~0.019/yr; mild overdispersion x2.3 leaves Poisson null valid",
        "Poisson z-scores exceed 4.0 for 2022 and 2023; 2024 drops to 0.976 indicating reversion"
      ],
      "recommended_action": "Investigate CI trend drivers (coding practice changes, medical inflation, benefit wording, or exposure mix); review and update CI pricing/reserving assumptions; monitor subsequent years to confirm 2024 reversion is structural rather than noise."
    }
  ]
}

